import unittest
from candidate import truncate_number

class TestTruncateNumber(unittest.TestCase):
    def test_truncate_number_positive_integer(self):
        self.assertEqual(truncate_number(5.0), 0.0)

    def test_truncate_number_positive_decimal(self):
        self.assertAlmostEqual(truncate_number(3.7), 0.7)

    def test_truncate_number_positive_large_decimal(self):
        self.assertAlmostEqual(truncate_number(1234.56789), 0.56789)

    def test_truncate_number_positive_small_decimal(self):
        self.assertAlmostEqual(truncate_number(1.0000001), 0.0000001)

    def test_truncate_number_boundary_just_below_integer(self):
        self.assertAlmostEqual(truncate_number(5.9999999), 0.9999999)

    def test_truncate_number_boundary_exactly_integer(self):
        self.assertEqual(truncate_number(4.0), 0.0)

    def test_truncate_number_negative_input(self):
        with self.assertRaises(ValueError):
            truncate_number(-3.5)

    def test_truncate_number_none_input(self):
        with self.assertRaises(TypeError):
            truncate_number(None)

    def test_truncate_number_non_numeric_input(self):
        with self.assertRaises(TypeError):
            truncate_number("3.5")

    def test_truncate_number_invalid_numeric_type(self):
        with self.assertRaises(TypeError):
            truncate_number(3.5j)

    def test_truncate_number_zero_input(self):
        self.assertEqual(truncate_number(0.0), 0.0)

    def test_truncate_number_fractional_zero(self):
        self.assertAlmostEqual(truncate_number(0.0000001), 0.0000001)
